import numpy as npfrom keras import layersfrom keras import optimizersfrom keras import Input, Modelimport matplotlib.pyplot as pltfrom fil import FeatureInteractionLayer, FeatureInteractionTransformerfrom sklearn.metrics import r2_scorefrom tqdm.keras import TqdmCallbackfrom sklearn.preprocessing import OneHotEncoderdef prepare_mlp_inputs(X, input_types):    cat_indices = [i for i, t in enumerate(input_types) if t[0] == 'cat']    cont_indices = [i for i, t in enumerate(input_types) if t[0] == 'cont']    X_cont = X[:, cont_indices]    # One-hot encode categorical    enc = OneHotEncoder(sparse_output=False, handle_unknown='ignore', categories='auto')    X_cat = enc.fit_transform(X[:, cat_indices])    # Concatenate    X_proc = np.concatenate([X_cont, X_cat], axis=1)    return X_procdef generate_synthetic_data(n_samples=1000, seed=42):    np.random.seed(seed)    num_features = 20    input_types = [['cont',0.0, 2.0, 10] if i % 2 == 0 else ['cat',3] for i in range(num_features)]    # Generate input matrix    X = np.random.rand(n_samples, num_features) * 2  # [0,2) for cont    for i, t in enumerate(input_types):        if t[0] == 'cat':            X[:, i] = np.random.randint(0, 3, size=n_samples)  # categorical: 0,1,2    # Define true interaction logic for target    # Groups: (0,1,2), (4,5,6), (10,11,12), (15,16,17)    def encode_cat(x):        return 1.0 if x == 1 else 0.5 if x == 2 else 0.0    y = (            X[:, 0] * np.vectorize(encode_cat)(X[:, 1]) * X[:, 2] +            X[:, 4] * np.vectorize(encode_cat)(X[:, 5]) * X[:, 6] +            X[:, 10] * np.vectorize(encode_cat)(X[:, 11]) * X[:, 12] +            X[:, 15] * np.vectorize(encode_cat)(X[:, 16]) * X[:, 17] +            np.random.normal(0, 0.05, size=n_samples)  # small noise    )    y = y.reshape(-1, 1)    return X, y, input_typesdef build_feature_interaction_model(input_types):    groups = [[(0, 1, 2),3], [(4, 5, 6),3], [(10, 11, 12),3], [(15, 16, 17),3]]    x_in = Input(shape=(len(input_types),))    x_feat_l = FeatureInteractionLayer(        input_types=input_types,        groups=groups,    )    x_feat = x_feat_l(x_in)    x_out = layers.Dense(1, activation="linear")(x_feat)    model = Model(x_in, x_out)    model.compile(optimizer=optimizers.AdamW(0.0001), loss='mse')    return model, x_feat_ldef build_mlp_baseline(input_dim):    x_in = Input(shape=(input_dim,))    x = layers.Dense(64, activation="relu")(x_in)    x = layers.Dropout(0.3)(x)    x = layers.Dense(64, activation="relu")(x)    x_out = layers.Dense(1, activation="linear")(x)    model = Model(x_in, x_out)    model.compile(optimizer=optimizers.AdamW(0.0001), loss='mse')    return modeldef run_comparison():    # Generate data    X, y, input_types = generate_synthetic_data(n_samples=2000)    n_train = 100    X_train, y_train = X[:n_train], y[:n_train]    X_val, y_val = X[n_train:], y[n_train:]    #print(X_train.max(), X_train.min())    # Models    fi_model, feature_layer = build_feature_interaction_model(input_types)    mlp_model = build_mlp_baseline(input_dim=40)    # Train both    print("Training Feature Interaction Model...")    fi_model.summary()    transformer = FeatureInteractionTransformer(feature_layer)    # from sklearn.linear_model import LinearRegression, ElasticNetCV, RidgeCV    # from sklearn.pipeline import Pipeline    # from sklearn.tree import DecisionTreeRegressor    #    #    # # Define full pipeline    # fi_model = Pipeline([    #     ("feature_transform", transformer),    #     ("regressor", RidgeCV())    # ])    #fi_model.fit(X_train, y_train)    hist_fi = fi_model.fit(X_train, y_train, validation_data=(X_val, y_val),                           epochs=200, batch_size=32, verbose=0, callbacks=[TqdmCallback()])    print("Training MLP Model...")    mlp_model.summary()    hist_mlp = mlp_model.fit(prepare_mlp_inputs(X_train,input_types), y_train, validation_data=(prepare_mlp_inputs(X_val,input_types), y_val),                             epochs=200, batch_size=32, verbose=0,  callbacks=[TqdmCallback()])    # # Plot comparison    # plt.plot(hist_fi.history['val_loss'], label='Feature Interaction Val Loss')    # plt.plot(hist_mlp.history['val_loss'], label='MLP Val Loss')    # plt.xlabel("Epoch")    # plt.ylabel("MSE Loss")    # plt.legend()    # plt.title("Validation Loss Comparison")    # plt.show()    # Print example predictions    preds_fi = fi_model.predict(X_val)    preds_mlp = mlp_model.predict(prepare_mlp_inputs(X_val,input_types))    # print("True:", y_val[:5].flatten())    print("FI model: R^2", r2_score(y_val, preds_fi))    print("MLP model: R^2", r2_score(y_val, preds_mlp))# Run demoif __name__ == "__main__":    run_comparison()